:root {
  --bg: #2b2b3c;
  --surface: #3a3a4e;
  --primary: #f0c060;
  --text: #e8e8f0;
  --accent: #6c6c8a;
  --danger: #e06060;
  --radius: 6px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.4;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 12px;
}

.board {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: 0 0 0 4px var(--accent), 0 8px 24px rgba(0,0,0,0.5);
  padding: 24px;
  width: 100%;
  max-width: 1100px;
}

.board-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.board-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--accent);
}

.add-form {
  display: flex;
  gap: 8px;
  flex: 1;
  min-width: 200px;
  max-width: 400px;
}

.add-form input {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--bg);
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  color: var(--text);
  min-width: 0;
}

.add-form input:focus {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
  border-color: var(--primary);
}

.add-form button {
  padding: 10px 20px;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: 700;
  background: var(--primary);
  color: var(--bg);
  border: 2px solid var(--primary);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.add-form button:hover {
  background: #f8d070;
  border-color: #f8d070;
}

.add-form button:active {
  transform: scale(0.96);
}

.add-form button:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}

.columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.column {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 12px;
  display: flex;
  flex-direction: column;
  min-height: 200px;
  border: 2px solid var(--accent);
}

.column-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--accent);
}

.column-title {
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--primary);
}

.count {
  background: var(--accent);
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 12px;
  min-width: 28px;
  text-align: center;
}

.card-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.card {
  background: var(--surface);
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  word-break: break-word;
}

.card-text {
  font-size: 0.95rem;
  line-height: 1.3;
}

.card-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.card-actions button {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--accent);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  padding: 0;
  line-height: 1;
}

.card-actions button:hover {
  background: var(--primary);
  color: var(--bg);
  border-color: var(--primary);
}

.card-actions button:active {
  transform: scale(0.92);
}

.card-actions button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.card-actions button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: var(--accent);
  color: var(--text);
  border-color: var(--accent);
}

.card-actions button.delete-btn:hover {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.empty-message {
  color: var(--accent);
  font-size: 0.875rem;
  text-align: center;
  padding: 16px 0;
  font-style: italic;
}

@media (max-width: 700px) {
  .columns {
    grid-template-columns: 1fr;
  }
  .board {
    padding: 16px;
  }
  .board-title {
    font-size: 1.4rem;
  }
}

@media (max-width: 400px) {
  body {
    padding: 12px 6px;
  }
  .board {
    padding: 12px;
  }
  .add-form {
    flex-direction: column;
  }
  .add-form button {
    width: 100%;
  }
}

(function () {
  'use strict';

  const columns = ['todo', 'doing', 'done'];
  let cards = [];
  let nextId = 1;

  const addForm = document.getElementById('add-form');
  const newCardInput = document.getElementById('new-card-input');

  function getColumnIndex(col) {
    return columns.indexOf(col);
  }

  function updateCounts() {
    columns.forEach(function (col) {
      const count = cards.filter(function (c) { return c.column === col; }).length;
      document.getElementById('count-' + col).textContent = count;
    });
  }

  function render() {
    columns.forEach(function (col) {
      const list = document.getElementById('list-' + col);
      list.innerHTML = '';
      const colCards = cards.filter(function (c) { return c.column === col; });
      if (colCards.length === 0) {
        const empty = document.createElement('li');
        empty.className = 'empty-message';
        empty.textContent = 'No cards';
        list.appendChild(empty);
      } else {
        colCards.forEach(function (card) {
          list.appendChild(createCardElement(card));
        });
      }
    });
    updateCounts();
  }

  function createCardElement(card) {
    const li = document.createElement('li');
    li.className = 'card';
    li.dataset.id = card.id;

    const text = document.createElement('span');
    text.className = 'card-text';
    text.textContent = card.text;
    li.appendChild(text);

    const actions = document.createElement('div');
    actions.className = 'card-actions';

    const colIndex = getColumnIndex(card.column);

    const leftBtn = document.createElement('button');
    leftBtn.type = 'button';
    leftBtn.textContent = '\u2190';
    leftBtn.setAttribute('aria-label', 'Move card left');
    leftBtn.disabled = colIndex === 0;
    leftBtn.addEventListener('click', function () { moveCard(card.id, -1); });
    actions.appendChild(leftBtn);

    const rightBtn = document.createElement('button');
    rightBtn.type = 'button';
    rightBtn.textContent = '\u2192';
    rightBtn.setAttribute('aria-label', 'Move card right');
    rightBtn.disabled = colIndex === columns.length - 1;
    rightBtn.addEventListener('click', function () { moveCard(card.id, 1); });
    actions.appendChild(rightBtn);

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.textContent = '\u2715';
    delBtn.className = 'delete-btn';
    delBtn.setAttribute('aria-label', 'Delete card');
    delBtn.addEventListener('click', function () { deleteCard(card.id); });
    actions.appendChild(delBtn);

    li.appendChild(actions);
    return li;
  }

  function addCard(text) {
    const trimmed = text.trim();
    if (!trimmed) return;
    cards.push({ id: nextId++, text: trimmed, column: 'todo' });
    render();
  }

  function moveCard(id, direction) {
    const card = cards.find(function (c) { return c.id === id; });
    if (!card) return;
    const newIndex = getColumnIndex(card.column) + direction;
    if (newIndex < 0 || newIndex >= columns.length) return;
    card.column = columns[newIndex];
    render();
  }

  function deleteCard(id) {
    cards = cards.filter(function (c) { return c.id !== id; });
    render();
  }

  addForm.addEventListener('submit', function (e) {
    e.preventDefault();
    addCard(newCardInput.value);
    newCardInput.value = '';
    newCardInput.focus();
  });

  render();
})();
